trait Comparable: PartialEq + Sized {
    fn cmp_to(&self, other: &Self) -> std::cmp::Ordering;
    fn greater_than(&self, other: &Self) -> bool {   // default method = mixin
        self.cmp_to(other).is_gt()
    }
}

fn largest<T: Comparable>(xs: &[T]) -> Option<&T> {  // monomorphized: static dispatch
    xs.iter().reduce(|a, b| if a.greater_than(b) { a } else { b })
}
